node server.js > "$TMPDIR/srv.log" 2>&1 & SRV=$!; sleep 1; node -e '
const { chromium } = require("@playwright/test");
(async () => {
  const b = await chromium.launch();
  for (const w of [390, 1280]) {
    const p = await b.newPage({ viewport: { width: w, height: 844 } });
    await p.goto("http://127.0.0.1:" + process.env.PORT + "/contact.html");
    const m = await p.evaluate(() => {
      const d = document.querySelector(".info-list dd");
      const card = d.closest(".card").getBoundingClientRect();
      const r = d.getBoundingClientRect();
      return {sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth,
              ddRight: +r.right.toFixed(1), cardRight: +card.right.toFixed(1), cardLeft: +card.left.toFixed(1)};
    });
    console.log("width", w, JSON.stringify(m));
    await p.screenshot({ path: process.env.TMPDIR + "/contact-" + w + "-after.png", fullPage: true });
    await p.close();
  }
  await b.close();
})();
' 2>&1 | grep -v 'npm notice'; kill $SRV; ls "$TMPDIR"/*after.png

